import{_ as t,o as s,c as r,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-23（材料 / 自旋电子学 / 多相催化）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-10-23-materials.md","filePath":"topics/materials/science-daily-2026-10-23-materials.md"}'),e={name:"topics/materials/science-daily-2026-10-23-materials.md"};function i(l,o,a,g,c,d){return s(),r("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-10-23-材料-自旋电子学-多相催化" tabindex="-1">科学日报 · 2026-10-23（材料 / 自旋电子学 / 多相催化） <a class="header-anchor" href="#科学日报-·-2026-10-23-材料-自旋电子学-多相催化" aria-label="Permalink to &quot;科学日报 · 2026-10-23（材料 / 自旋电子学 / 多相催化）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-23.md</code> — 第42期 ｜ 科学板块（2 篇） 落盘说明：文件名带 <code>-materials</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code> 及 10-21、10-22 晨报）。</p></blockquote><hr><h2 id="科学日报-2026-10-23-反铁磁隧道结的「八极矩自旋力矩」翻转——tmr-363-且能被电流写入" tabindex="-1">科学日报 2026-10-23：反铁磁隧道结的「八极矩自旋力矩」翻转——TMR 363% 且能被电流写入 <a class="header-anchor" href="#科学日报-2026-10-23-反铁磁隧道结的「八极矩自旋力矩」翻转——tmr-363-且能被电流写入" aria-label="Permalink to &quot;科学日报 2026-10-23：反铁磁隧道结的「八极矩自旋力矩」翻转——TMR 363% 且能被电流写入&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-23.md</code> ｜ DOI: 10.1038/s41586-026-11172-5</p></blockquote><ul><li>背景（一个「被假定不可能」的领域）：铁磁隧道结靠 <strong>TMR（读）</strong> 与 <strong>自旋转移矩（写）</strong> 同时实现磁序的电学探测与调控；<strong>反铁磁体没有净磁矩</strong>，因此这两个效应长期被认为在全反铁磁隧道结（AATJ）中都不显著。</li><li>反转的第一步：近年发现<strong>手性反铁磁体</strong>因「<strong>动量依赖的自旋极化</strong> + <strong>团簇磁八极矩</strong>」（自旋劈裂能带的体现）确有可观 TMR。</li><li>本条的突破：<strong>逆效应</strong>（自旋转移矩的反铁磁对应物）此前被认定不存在（总电流<strong>自旋中性</strong>）——作者做出<strong>纳米尺度 AATJ：PtMn₃ | MgO | PtMn₃</strong>，实现了电流驱动的翻转，命名为 <strong>八极矩驱动的自旋转移矩（OTT, octupole-driven spin-transfer torque）</strong>。 <ul><li><strong>室温 TMR = 363%</strong></li><li><strong>翻转电流密度 ~10 MA cm⁻²</strong></li></ul></li><li>机制：理论把 OTT 归因于跨结的「<strong>内子晶格 / 间子晶格自旋流不平衡</strong>」，<strong>等价地</strong>也表述为每层 PtMn₃ 存在<strong>非零的净团簇八极矩极化</strong>。</li><li>结论/前景：确立<strong>反铁磁自旋电子学的新材料平台</strong>，指向<strong>深度微缩的磁性存储器</strong>与<strong>室温太赫兹器件</strong>。</li><li>洞察（对本库 <code>materials</code> × <code>quantum-physics</code>）：本库 10-21 刚记 WSe₂/WS₂ 的<strong>手性自旋模式</strong>（同样是「自旋劈裂能带 + 栅压编程集体态」），本条是<strong>同一物理在器件层的兑现</strong> —— <strong>能带的自旋劈裂把「应被对称性禁止的效应」变成了可用效应</strong>。迁移成一条可复用判据：<strong>当某个效应因「对称性论证」被判死，先问「是哪种对称性被破缺、破缺后被释放的是哪个更高级的序参量（这里是团簇八极矩，而非磁化）」</strong>。这条与本库「极限是工具的属性」同构：<strong>不是现象不存在，而是过去没有合适的序参量去描述它</strong>。</li></ul><hr><h2 id="科学日报-2026-10-23-分子筛里「把分子摆对笼子」——空间限域把烯烃羰基化产物从叔羧酸改写成伯-仲羧酸" tabindex="-1">科学日报 2026-10-23：分子筛里「把分子摆对笼子」——空间限域把烯烃羰基化产物从叔羧酸改写成伯/仲羧酸 <a class="header-anchor" href="#科学日报-2026-10-23-分子筛里「把分子摆对笼子」——空间限域把烯烃羰基化产物从叔羧酸改写成伯-仲羧酸" aria-label="Permalink to &quot;科学日报 2026-10-23：分子筛里「把分子摆对笼子」——空间限域把烯烃羰基化产物从叔羧酸改写成伯/仲羧酸&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-23.md</code> ｜ DOI: 10.1038/s41586-026-11183-2</p></blockquote><ul><li>背景：<strong>羰基化</strong>用于生产醛、羧酸与酯，通常依赖<strong>均相金属配合物 + 配体 + 碘促进剂</strong>；矿物酸质子也能催化（<strong>Koch 反应</strong>），而 <strong>Brønsted 酸性分子筛</strong>可做<strong>多相 Koch 型催化剂</strong>，但产物<strong>只限于叔羧酸</strong>（一个明确的产物天花板）。</li><li>方法（两个条件叠加）：<strong>定向利用分子筛的空间限域</strong> + <strong>高 CO/烯烃比</strong>。</li><li>结果： <ul><li><strong>FER 分子筛 + CO/烯烃比 360</strong>：主产物变为<strong>伯、仲羧酸</strong>。</li><li><strong>乙烯 → 丙酸（PA）</strong>：<strong>80% 选择性，稳定运行 100 h</strong>。</li><li><strong>丙烯 → 异丁酸（IBA）</strong>：<strong>95% 选择性，稳定运行 750 h</strong>。</li><li><strong>敏感性</strong>：CO/烯烃比降到 24 / 90，两条路线的选择性分别跌至 <strong>61% / 57%</strong> → 高 CO 分压是维持该路径的前提。</li></ul></li><li>活性位归属（实验 + 理论）：乙烯羰基化的主活性位是 <strong>8 元环（8-MR）空腔中的 T2–O5</strong>；丙烯羰基化的主活性位是 <strong>10 元环（10-MR）中的 T3–O1</strong>。</li><li>结论：<strong>选择性来自「把分子摆在哪个笼子里」</strong>，而不是改变化学本身；为多相羰基化工艺给出「孔结构 + 气氛比」的设计前提。</li><li>洞察（对本库 <code>materials</code>）：与同期的反铁磁条目、以及本库 10-21/10-22 的「螺旋位错当组织指令」「酶热嵌进聚酯」合成<strong>同一条主线</strong> —— <strong>几何/空间就是功能</strong>。这里更值钱的是一条<strong>工艺课</strong>：目标产物的改变需要<strong>两个条件同时满足</strong>（限域 + 高 CO/烯烃比），且<strong>两个反应的活性位在不同的环尺寸上</strong>（8-MR vs 10-MR）→ <strong>同一个框架（FER）里存在两套可分别寻址的位点</strong>。迁移判据：<strong>面对「催化剂只有一种产物」的天花板，先问「是活性位几何限定，还是气氛/传质条件限定」——本条证明两者都得动，而且动对了就能各取所需。</strong></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ 第42期 科学板块</p></blockquote><p>关键词：全反铁磁隧道结、AATJ、PtMn3、MgO、八极矩驱动自旋转移矩、OTT、TMR 363%、10 MA cm-2、团簇八极矩、自旋劈裂能带、内子晶格自旋流不平衡、反铁磁自旋电子学、室温太赫兹、对称性判死不等于效应不存在、序参量选对；分子筛羰基化、Koch反应、FER、空间限域、CO/烯烃比360、伯仲羧酸、丙酸80%选择性100h、异丁酸95%选择性750h、T2-O5、8元环、T3-O1、10元环、几何即功能、活性位可分别寻址</p><p>关联：<code>topics/materials/science-daily-2026-10-22-materials.md</code>（嵌酶聚酯 + 人工金属酶）、<code>topics/materials/science-daily-2026-10-21-materials.md</code>（螺旋位错超螺旋 + WSe₂/WS₂ 手性自旋模式）、<code>topics/physics/science-daily-2026-10-23-physics.md</code>、<code>topics/materials/index.md</code></p>',14)])])}const u=t(e,[["render",i]]);export{p as __pageData,u as default};
